export const mentalCases={};
export const mentalDirectCases={};
function add(id,scenario,source,roles){mentalCases['SIT-NP5-'+id]={scenario,source:S[source]??source,...roles};}

const frozenDirectKeys={101:[3,0,1,2,3],102:[2,3,2,1,0],103:[1,0,3,0,2],104:[0,2,0,3,2],105:[3,0,1,2,3],106:[2,3,2,1,0],107:[1,0,3,0,2],108:[0,2,0,3,2],114:[2,3,0,1,0],115:[1,0,3,0,2],116:[0,2,0,3,2],119:[1,0,3,0,2],120:[0,2,0,3,2]};
function group(number,scenario,source,items){
 items.forEach(([question,correct,...rest],i)=>{
  rest.splice(frozenDirectKeys[number][i],0,correct);
  mentalDirectCases[`NP5-${number}-${i+1}`]={question,scenario,source:S[source]??source,choices:rest.map(x=>x[0]),reasons:rest.map(x=>x[1]),choiceSources:rest.map(x=>x[2]??S[source]??source),...(i===4?{unsafeAnswer:true}:{})};
 });
}
function direct(id,key,scenario,question,source,correct,...rest){
 rest.splice(key,0,correct);const src=S[source]??source;
 mentalDirectCases[id]={scenario,question,source:src,choices:rest.map(x=>x[0]),reasons:rest.map(x=>x[1]),choiceSources:rest.map(x=>x[2]??src)};
}

direct('ORIG-NP5-personality-disorders-01',2,
 'A patient with borderline personality disorder is considering dialectical behavior therapy and asks which aim distinguishes the proposed skills program.',
 'Which treatment goal should the nurse describe?','personality',
 ['Develop mindfulness, emotion-regulation, distress-tolerance, and interpersonal skills while reducing harmful behavior','DBT combines skills and therapeutic work to manage intense emotions, improve relationships, and reduce self-destructive behavior.'],
 ['Induce a monitored therapeutic seizure under anesthesia','This describes ECT, used for selected severe illnesses; it is not the defining method or skills goal of DBT.',S.brain],
 ['Practice exposure while resisting compulsive checking rituals','This describes ERP for OCD. DBT addresses a different skills formulation in this case.',S.ocd],
 ['Guarantee that no emotional distress will occur after a single meeting','No psychological treatment guarantees permanent absence of distress. DBT develops skills through ongoing work.']);

direct('ORIG-NP5-somatic-behavioral-therapies-01',1,
 'Before modern electroconvulsive therapy, an adult is told that a short-acting general anesthetic and a muscle relaxant will be used by the trained treatment team.',
 'Which explanation best describes the purpose of these medicines?','brain',
 ['The anesthetic prevents awareness and pain during the procedure, and the relaxant limits seizure-related body movement','ECT produces therapeutic brain seizure activity. Anesthesia and muscle relaxation support a controlled procedure with physiological monitoring.'],
 ['The anesthetic guarantees no memory effects can occur','Cognitive and memory effects remain possible and require informed discussion and monitoring.'],
 ['The muscle relaxant replaces the electrical stimulation and brain seizure','The relaxant limits movement; it does not provide the intended brain stimulation or substitute for the therapeutic seizure.'],
 ['The medicines make airway and circulatory monitoring unnecessary','Anesthesia and the procedure require a trained team and monitoring, not less oversight.']);

direct('MMCQA-bf1f425b-d7e1-4ccf-98db-cc0fdd8237b2',2,
 'An adult with schizophrenia has persistent symptoms despite two sequential antipsychotic trials at adequate dose and duration, including a non-clozapine second-generation drug. Adherence and the diagnosis have been reviewed.',
 'Which medication should the nurse anticipate the prescriber will offer for treatment resistance?','psychosis',
 ['Clozapine','NICE recommends offering clozapine after inadequate response to at least two adequate antipsychotic trials, including a second-generation agent. Specific monitoring and risk discussion are required.'],
 ['Haloperidol as the mandatory next step instead of considering clozapine','Haloperidol can treat psychosis, but this completed treatment-resistance assessment meets the recommendation to consider clozapine rather than another mandatory routine switch.'],
 ['Fluphenazine as a guaranteed solution after any two failed drugs','Fluphenazine is an antipsychotic, but there is no guarantee of response and it does not replace the clozapine recommendation here.'],
 ['Olanzapine solely because a third non-clozapine trial must always precede clozapine','Olanzapine has a role in psychosis treatment, but a universal third-trial prerequisite is not the stated recommendation.']);

direct('EXP2-NP5-foundations-of-mental-health-nursing',0,
 'A psychiatric unit deliberately uses a safe physical setting, predictable routines, respectful boundaries, and collaborative activities to support recovery.',
 'Which term best describes this planned use of the treatment environment?','milieu',
 ['Therapeutic milieu','A therapeutic milieu uses the physical and social environment to support safety, participation, coping, and recovery.'],
 ['Seclusion','Seclusion is a restrictive intervention with a specific safety indication; it is not the general recovery environment described.',S.restraint],
 ['Pharmacotherapy','Pharmacotherapy uses medicines. It may occur within the unit but does not name the planned environmental approach.'],
 ['A token economy alone','A token economy uses contingent reinforcement for selected behaviors. It is narrower than the whole therapeutic environment.',S.learning]);

direct('EXP2-NP5-therapeutic-stress-models',1,
 'Before an examination, a student thinks, “This may be a worthwhile challenge rather than a disaster.” The student has not yet considered study time, available help, or a study plan.',
 'In a transactional stress model, which process is most directly illustrated?','stress',
 ['Primary appraisal','Primary appraisal concerns the event’s meaning, including threat, loss, or challenge. The student is interpreting what the examination means.'],
 ['Secondary appraisal','Secondary appraisal evaluates coping resources and options, such as available time or help; those have not yet been considered.'],
 ['Problem-focused coping through carrying out a study plan','Taking practical action to manage the demand would be coping; no study plan is yet being implemented.'],
 ['Avoidance behavior','Avoidance involves disengaging from or evading the demand; the statement instead appraises it as a challenge.']);

direct('EXP2-NP5-anxiety-anxiety-related-disorders',2,
 'An adult avoids buses, crowded shops, and being outside alone because escape or help might be difficult during panic-like symptoms. The persistent fear restricts daily activities.',
 'Which anxiety pattern is most consistent with the stated reason for avoidance?','agoraphobia',
 ['Agoraphobic avoidance','Fear of situations where escape or help may be difficult, including travel, crowds, and being alone outside home, fits this pattern. Full assessment determines the diagnosis.'],
 ['Performance-only social anxiety','That pattern centers on scrutiny or negative evaluation during performance, such as speaking publicly; the stated concern is escape and access to help.',S.socialAnxiety],
 ['Social anxiety centered on embarrassment under observation','Fear of others’ judgment can cause social avoidance, but it is not the main reason described here.',S.socialAnxiety],
 ['Compulsions used to neutralize intrusive obsessions','OCD rituals are performed in response to obsessions or rigid rules; the scenario describes feared situations and escape concerns.',S.ocd]);

direct('EXP2-NP5-trauma-related-disorders',3,
 'Twelve days after an assault, an adult has intrusive memories, poor sleep, and avoidance that affect functioning. No immediate medical instability is identified.',
 'Which assessment statement is most accurate?','trauma',
 ['Assess acute trauma symptoms and safety; the PTSD duration criterion is not yet met','PTSD requires symptoms beyond one month. Earlier clinically important symptoms still merit assessment, support, and appropriate treatment or follow-up.'],
 ['Confirm chronic PTSD solely because intrusive memories are present','Intrusive memories are relevant, but timing and the complete criteria do not support that conclusion.'],
 ['Withhold all care until a full month has passed','Early distress and impairment deserve care; time criteria do not justify abandonment.'],
 ['Diagnose acute stress disorder from timing alone','The early time frame is compatible with that differential, but a full symptom and diagnostic assessment is still needed.']);

direct('EXP2-NP5-mood-disorders',0,
 'A client says, “I have enough energy for music and gardening, but I no longer enjoy either activity, even when I try.” The nurse is completing a mood assessment.',
 'Which symptom is most directly described?','nimhDepression',
 ['Anhedonia','The central feature is reduced interest or pleasure in previously enjoyed activities, distinct from energy loss alone. It contributes to a full assessment rather than proving a diagnosis.'],
 ['Grandiosity','Grandiosity involves an inflated view of importance, ability, or status; the statement describes loss of enjoyment.',S.nimhBipolar],
 ['Flight of ideas','Flight of ideas concerns rapid shifts in thought and speech, not a reduced capacity for pleasure.',S.nimhBipolar],
 ['Avolition','Avolition is reduced initiation or motivation. This client reports trying the activities but not enjoying them, making anhedonia more direct.',S.nimhSchizophrenia]);

